"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ShieldCheck, Calendar, Info, CheckCircle2, ChevronRight, Copy } from "lucide-react";
import { useParams } from "next/navigation";

interface Acordo {
  token: string;
  valorOriginal: number;
  valorComDesconto: number;
  clienteNome: string;
  status: string;
  vencimento: string;
}

export default function PaymentPortal() {
  const params = useParams();
  const token = params.token as string;
  
  const [acordo, setAcordo] = useState<Acordo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [pixData, setPixData] = useState<{ pix_qrcode: string, pix_copia_cola: string } | null>(null);
  const [copied, setCopied] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [paid, setPaid] = useState(false);

  useEffect(() => {
    if (token) {
      fetch(`http://localhost:8000/p/${token}`)
        .then(res => {
          if (!res.ok) throw new Error("Not found");
          return res.json();
        })
        .then(data => {
          setAcordo(data);
          if (data.status === "PAGO") setPaid(true);
        })
        .catch(() => setError(true))
        .finally(() => setLoading(false));
    }
  }, [token]);

  const handleGeneratePix = async () => {
    setGenerating(true);
    try {
      const res = await fetch(`http://localhost:8000/p/${token}/gerar-pix`, { method: "POST" });
      if (res.ok) {
        const data = await res.json();
        setPixData(data);
        
        // MOCK: simulate real-time payment after 5 seconds of generating PIX
        setTimeout(() => {
          setPaid(true);
        }, 5000);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setGenerating(false);
    }
  };

  const copyToClipboard = () => {
    if (pixData) {
      navigator.clipboard.writeText(pixData.pix_copia_cola);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-950">
        <div className="w-12 h-12 rounded-full border-4 border-zinc-800 border-t-indigo-500 animate-spin"></div>
      </div>
    );
  }

  if (error || !acordo) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <div className="w-16 h-16 rounded-full bg-rose-500/10 flex items-center justify-center text-rose-500 mb-6">
          <Info className="w-8 h-8" />
        </div>
        <h2 className="text-2xl font-bold text-white mb-2">Acordo indisponível</h2>
        <p className="text-zinc-400 text-center max-w-sm">
          Este link pode ter expirado ou o pagamento já foi compensado.
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-hidden">
      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5, type: "spring" }}
        className="glass-panel w-full max-w-md p-8 relative z-10"
      >
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-16 h-16 mx-auto bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-500/20 mb-4">
            <ShieldCheck className="w-8 h-8 text-white" />
          </div>
          <h1 className="text-2xl font-bold text-white tracking-tight">Proposta de Quitação</h1>
          <p className="text-zinc-400 text-sm mt-1">Olá, {acordo.clienteNome.split(' ')[0]}</p>
        </div>

        <AnimatePresence mode="wait">
          {paid ? (
            <motion.div
              key="paid"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex flex-col items-center text-center py-6"
            >
              <div className="w-20 h-20 rounded-full bg-emerald-500/20 flex items-center justify-center mb-6 border border-emerald-500/30">
                <CheckCircle2 className="w-10 h-10 text-emerald-400" />
              </div>
              <h2 className="text-2xl font-bold text-emerald-400 mb-2">Pagamento Confirmado!</h2>
              <p className="text-zinc-400 mb-6">
                Seu pagamento foi identificado e a baixa no sistema será realizada em instantes.
              </p>
              <div className="w-full bg-zinc-900/50 rounded-xl p-4 border border-white/5">
                <div className="flex justify-between text-sm mb-2">
                  <span className="text-zinc-500">Valor pago</span>
                  <span className="text-white font-medium">{formatCurrency(acordo.valorComDesconto)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-500">Comprovante</span>
                  <span className="text-white font-medium">#{token.substring(0,8).toUpperCase()}</span>
                </div>
              </div>
            </motion.div>
          ) : !pixData ? (
            <motion.div 
              key="details"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
            >
              {/* Values */}
              <div className="space-y-4 mb-8">
                <div className="flex justify-between items-center p-4 rounded-xl bg-rose-500/5 border border-rose-500/10">
                  <span className="text-zinc-400">Valor Original</span>
                  <span className="text-zinc-300 line-through decoration-rose-500/50">{formatCurrency(acordo.valorOriginal)}</span>
                </div>
                
                <div className="flex justify-between items-center p-5 rounded-xl bg-emerald-500/10 border border-emerald-500/20 relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-1 h-full bg-emerald-500"></div>
                  <div>
                    <span className="block text-emerald-400 text-sm font-semibold mb-1">Pagamento à vista</span>
                    <span className="text-3xl font-bold text-white">{formatCurrency(acordo.valorComDesconto)}</span>
                  </div>
                  <div className="text-right">
                    <span className="block text-xs text-zinc-400 mb-1">Desconto de</span>
                    <span className="text-lg font-bold text-emerald-400">
                      {Math.round((1 - acordo.valorComDesconto / acordo.valorOriginal) * 100)}%
                    </span>
                  </div>
                </div>
              </div>

              {/* Action */}
              <button 
                onClick={handleGeneratePix}
                disabled={generating}
                className="w-full py-4 px-4 bg-indigo-500 hover:bg-indigo-600 active:bg-indigo-700 text-white font-bold rounded-xl transition-colors flex items-center justify-center gap-2 group disabled:opacity-70"
              >
                {generating ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                  <>
                    Gerar código PIX
                    <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                  </>
                )}
              </button>
              
              <div className="mt-6 flex items-center justify-center gap-2 text-xs text-zinc-500">
                <ShieldCheck className="w-4 h-4" />
                Ambiente 100% seguro e criptografado
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="pix"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="flex flex-col items-center"
            >
              <h3 className="text-lg font-medium text-white mb-6">Pague via PIX</h3>
              
              {/* Fake QR Code Area */}
              <div className="w-48 h-48 bg-white rounded-xl mb-6 p-2 relative">
                {/* SVG mock of QR code */}
                <div className="w-full h-full border-4 border-dashed border-zinc-200 flex items-center justify-center text-zinc-400 text-sm font-medium text-center">
                  QR Code PIX<br/>(Simulação)
                </div>
              </div>

              <div className="w-full space-y-3">
                <p className="text-sm text-zinc-400 text-center">Ou copie o código abaixo:</p>
                <button 
                  onClick={copyToClipboard}
                  className="w-full flex items-center justify-between p-4 rounded-xl bg-zinc-900 border border-white/10 hover:bg-zinc-800 transition-colors group"
                >
                  <span className="text-zinc-500 text-sm truncate max-w-[200px]">
                    {pixData.pix_copia_cola}
                  </span>
                  <div className="flex items-center gap-2 text-indigo-400">
                    <span className="text-xs font-semibold">{copied ? "COPIADO!" : "COPIAR"}</span>
                    <Copy className="w-4 h-4 group-hover:scale-110 transition-transform" />
                  </div>
                </button>
              </div>

              {/* Waiting status */}
              <div className="mt-8 flex items-center gap-3 text-sm text-zinc-400 bg-zinc-900/50 py-2 px-4 rounded-full border border-white/5">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                Aguardando pagamento...
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}
